
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mobile_e164 VARCHAR(16) NOT NULL UNIQUE,ideamart_subscriber_id VARCHAR(120) NULL UNIQUE,otp_verified_demo TINYINT(1) NOT NULL DEFAULT 0,phone_verified_real TINYINT(1) NOT NULL DEFAULT 0,role ENUM('user','admin') NOT NULL DEFAULT 'user',account_status ENUM('active','blocked') NOT NULL DEFAULT 'active',blocked_at DATETIME NULL,last_login_at DATETIME NULL,preferred_locale VARCHAR(10) NOT NULL DEFAULT 'si-LK',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(account_status,created_at),INDEX(last_login_at)) ENGINE=InnoDB;
CREATE TABLE authentication_otps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,mobile_e164 VARCHAR(16) NOT NULL,code_hash VARCHAR(255) NULL,delivery_mode ENUM('demo','sms') NOT NULL,expires_at DATETIME NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(mobile_e164,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE user_subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,status ENUM('active','inactive','cancelled','expired','pending') NOT NULL,is_simulated TINYINT(1) NOT NULL DEFAULT 1,provider ENUM('simulated','ideamart','mspace') NOT NULL DEFAULT 'simulated',provider_status VARCHAR(30) NULL,frequency VARCHAR(60) NULL,accepted_at DATETIME NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,notified_at VARCHAR(40) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,status,ends_at),INDEX(provider,provider_status),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE service_catalog (id TINYINT UNSIGNED PRIMARY KEY,slug VARCHAR(60) NOT NULL UNIQUE,price_lkr DECIMAL(10,2) NOT NULL DEFAULT 20,enabled TINYINT(1) NOT NULL DEFAULT 1,configuration_json JSON NOT NULL) ENGINE=InnoDB;
CREATE TABLE horoscope_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,service_id TINYINT UNSIGNED NOT NULL,status ENUM('processing','completed','failed') NOT NULL,locale VARCHAR(10) NOT NULL,questionnaire_json JSON NOT NULL,idempotency_key VARCHAR(100) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,UNIQUE(user_id,idempotency_key),INDEX(service_id,status,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES service_catalog(id)) ENGINE=InnoDB;
CREATE TABLE horoscope_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL UNIQUE,result_json JSON NOT NULL,model_name VARCHAR(100) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES horoscope_requests(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE payment_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,request_id BIGINT UNSIGNED NULL,amount DECIMAL(10,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'LKR',status ENUM('simulated_confirmed','authorized','paid','failed','refunded') NOT NULL,is_simulated TINYINT(1) NOT NULL DEFAULT 1,provider ENUM('simulated','ideamart','mspace') NOT NULL DEFAULT 'simulated',external_reference VARCHAR(120) NULL,provider_reference VARCHAR(120) NULL,description VARCHAR(255) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,external_reference),INDEX(status,created_at),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(request_id) REFERENCES horoscope_requests(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE ai_usage_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,request_id BIGINT UNSIGNED NOT NULL,model_name VARCHAR(100) NOT NULL,total_tokens INT UNSIGNED NOT NULL DEFAULT 0,duration_ms INT UNSIGNED NOT NULL DEFAULT 0,estimated_cost DECIMAL(12,6) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),FOREIGN KEY(request_id) REFERENCES horoscope_requests(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE rahu_kalaya_cache (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,local_date DATE NOT NULL,location_key VARCHAR(80) NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,source_details VARCHAR(255) NOT NULL,calculated_at DATETIME NOT NULL,UNIQUE(local_date,location_key)) ENGINE=InnoDB;
CREATE TABLE consent_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,consent_type VARCHAR(80) NOT NULL,consent_text TEXT NOT NULL,locale VARCHAR(10) NOT NULL,accepted_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ip_hash CHAR(64) NULL,INDEX(user_id,consent_type),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE audit_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event_type VARCHAR(100) NOT NULL,metadata_json JSON NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(event_type,created_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
